import{L as e,b as t,x as n}from"./vue-Dpdj5O0f.js";import{oi as r}from"./common-DOddpOND.js";var i=JSON.parse(`{"path":"/tool/note/gshasgik/","title":"Plume 构建错误排查与修复 | Note","lang":"zh-CN","frontmatter":{"title":"Plume 构建错误排查与修复","createTime":"2026/09/05 10:06:00","permalink":"/tool/note/gshasgik/"},"readingTime":{"minutes":2.16,"words":649},"git":{},"filePathRelative":"tool/note/004.vuepress-pnpm-troubleshooting.md","headers":[]}`),a={name:`004.vuepress-pnpm-troubleshooting.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>在本地运行开发服务器或在 CI 环境（Netlify / Vercel / GitHub Actions）部署 VuePress 项目时，常遇到依赖版本不匹配或锁文件过期的错误。此类问题通常源于手动改动 <code>package.json</code> 后未同步锁文件，或主题对 VuePress 核心包有固定版本要求。本文整理两条典型报错链路的排查与修复方法，以及相应的版本管理建议。</p><h2 id="一、本地运行-npm-run-docs-dev-提示依赖版本不匹配" tabindex="-1"><a class="header-anchor" href="#一、本地运行-npm-run-docs-dev-提示依赖版本不匹配"><span>一、本地运行 <code>npm run docs:dev</code> 提示依赖版本不匹配</span></a></h2><h3 id="错误现象" tabindex="-1"><a class="header-anchor" href="#错误现象"><span>错误现象</span></a></h3><p>本地终端运行开发指令时，抛出如下警告或错误：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span>vuepress-theme-plume: ⚠ 以下依赖版本不匹配：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>devDependencies:</span></span>
<span class="line"><span>  @vuepress/bundler-vite: 2.0.0-rc.31 -&gt; 2.0.0-rc.30</span></span>
<span class="line"><span>  vuepress: 2.0.0-rc.31 -&gt; 2.0.0-rc.30</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请更新依赖至正确的版本。</span></span></code></pre></div><h3 id="原因分析" tabindex="-1"><a class="header-anchor" href="#原因分析"><span>原因分析</span></a></h3><p>当前使用的主题（<code>vuepress-theme-plume</code>）要求固定的 VuePress 核心包版本（如 <code>2.0.0-rc.30</code>），而项目实际安装的是更高的版本（如 <code>2.0.0-rc.31</code>）。</p><h3 id="解决方法" tabindex="-1"><a class="header-anchor" href="#解决方法"><span>解决方法</span></a></h3><ol><li><p><strong>锁定 <code>package.json</code> 中的版本号</strong></p><p>去除 <code>@vuepress/bundler-vite</code> 和 <code>vuepress</code> 版本号前面的 <code>^</code> 或 <code>~</code> 符号：</p><div class="language-json" data-highlighter="shiki" data-ext="json" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-json"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;devDependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@vuepress/bundler-vite&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0.0-rc.30&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;vuepress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0.0-rc.30&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><p><strong>重新安装本地依赖</strong></p><p>使用项目对应的包管理器重新安装。</p><p>使用 pnpm：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>使用 npm：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node_modules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package-lock.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div></li></ol><h2 id="二、ci-构建报错-err-pnpm-outdated-lockfile" tabindex="-1"><a class="header-anchor" href="#二、ci-构建报错-err-pnpm-outdated-lockfile"><span>二、CI 构建报错 <code>ERR_PNPM_OUTDATED_LOCKFILE</code></span></a></h2><h3 id="错误现象-1" tabindex="-1"><a class="header-anchor" href="#错误现象-1"><span>错误现象</span></a></h3><p>推送代码后 CI 构建失败并输出：</p><div class="language-text" data-highlighter="shiki" data-ext="text" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-text"><span class="line"><span> ERR_PNPM_OUTDATED_LOCKFILE  Cannot install with &quot;frozen-lockfile&quot; because pnpm-lock.yaml is not up to date with &lt;ROOT&gt;/package.json</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Failure reason:</span></span>
<span class="line"><span>  specifiers in the lockfile ({&quot;@vuepress/bundler-vite&quot;:&quot;2.0.0-rc.31&quot;, ...})</span></span>
<span class="line"><span>  don&#39;t match specs in package.json ({&quot;@vuepress/bundler-vite&quot;:&quot;2.0.0-rc.30&quot;, ...})</span></span></code></pre></div><h3 id="原因分析-1" tabindex="-1"><a class="header-anchor" href="#原因分析-1"><span>原因分析</span></a></h3><p>CI 环境默认开启 <code>--frozen-lockfile</code>（冻结锁文件模式）。修改 <code>package.json</code> 中的依赖版本后，若未更新或未提交最新的 <code>pnpm-lock.yaml</code>，CI 会检测到锁文件与配置不一致而中断构建。</p><h3 id="解决方法-1" tabindex="-1"><a class="header-anchor" href="#解决方法-1"><span>解决方法</span></a></h3><ol><li><p><strong>在本地重新安装依赖以更新锁文件</strong></p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div></li><li><p><strong>提交更新后的 <code>package.json</code> 与 <code>pnpm-lock.yaml</code> 并推送</strong></p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm-lock.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fix: update pnpm-lock.yaml after vuepress version sync&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span></span></code></pre></div></li></ol><div class="hint-container important"><p class="hint-container-title">重要</p><p>CI 使用 <code>--frozen-lockfile</code> 时，必须把本地生成的 <code>pnpm-lock.yaml</code> 一起提交；只提交 <code>package.json</code> 而漏掉锁文件，CI 仍会失败。</p></div><h2 id="三、最佳实践建议" tabindex="-1"><a class="header-anchor" href="#三、最佳实践建议"><span>三、最佳实践建议</span></a></h2><ul><li><strong>版本锁死</strong>：使用 VuePress 2.0 预发布（RC）版本及配套主题时，建议严格锁定版本号（不写 <code>^</code> 或 <code>~</code>），规避次级版本更新引入的不兼容问题。</li><li><strong>锁文件同步</strong>：每次手动变更 <code>package.json</code> 后，务必在本地运行包管理器安装命令（如 <code>pnpm install</code>），确保锁文件更新后再提交 Git。</li></ul>`,21)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};